import '@gravity-ui/uikit/styles/styles.css';
import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import Yagr from '@gravity-ui/yagr';
import {CpuLoadChart} from './CpuLoadChart/CpuLoadChart';
import type {CpuLoadChartHandle} from './CpuLoadChart/CpuLoadChart';
import {createCpuSource} from './mock/cpuSource';

const w = window as any;
// счётчики ресурсов
const counts = {listenersAdded: 0, listenersRemoved: 0, roObserve: 0, roDisconnect: 0, raf: 0, cafHit: 0};
const addL = EventTarget.prototype.addEventListener;
const remL = EventTarget.prototype.removeEventListener;
EventTarget.prototype.addEventListener = function (this: any, t: string, ...r: any[]) {
  if (['pointerdown', 'pointerup', 'pointercancel', 'pointerleave'].includes(t)) counts.listenersAdded++;
  return (addL as any).call(this, t, ...r);
};
EventTarget.prototype.removeEventListener = function (this: any, t: string, ...r: any[]) {
  if (['pointerdown', 'pointerup', 'pointercancel', 'pointerleave'].includes(t)) counts.listenersRemoved++;
  return (remL as any).call(this, t, ...r);
};
const RO = window.ResizeObserver;
window.ResizeObserver = class extends RO {
  observe(t: Element, o?: ResizeObserverOptions) { counts.roObserve++; super.observe(t, o); }
  disconnect() { counts.roDisconnect++; super.disconnect(); }
} as any;

let instance: any = null;
const origSet = (Yagr.prototype as any).setSeries;
(Yagr.prototype as any).setSeries = function (...a: any[]) { instance = this; return origSet.apply(this, a); };

const source = createCpuSource();
const ref = React.createRef<CpuLoadChartHandle>();
const root = ReactDOM.createRoot(document.getElementById('root')!);
const App = () => (
  <ThemeProvider theme="light"><div style={{height: 300, width: 800}}><CpuLoadChart ref={ref} initialData={source.history} /></div></ThemeProvider>
);
w.mount = () => root.render(<App />);
w.unmount = () => root.render(<div />);
w.counts = counts;
w.info = () => ({
  canvases: document.querySelectorAll('canvas').length,
  tooltips: document.querySelectorAll('.yagr-tooltip').length,
  timeline: instance?.config.timeline.length,
  series: instance?.config.series[0].data.length,
  first: instance?.config.timeline[0],
  last: instance?.config.timeline.at(-1),
  uplotLen: instance?.uplot.data[0].length,
});
// добавить n точек подряд и измерить время до следующего кадра после применения
w.pushAndMeasure = async (n: number) => {
  const last = instance?.config.timeline.at(-1) ?? Date.now();
  const samples = Array.from({length: n}, (_, i) => ({t: last + (i + 1) * 2000, v: 50 + (i % 10)}));
  const t0 = performance.now();
  ref.current!.append(samples);
  await new Promise((r) => requestAnimationFrame(() => r(null)));  // наш flush (зарегистрирован раньше)
  const t1 = performance.now();
  await new Promise((r) => requestAnimationFrame(() => r(null)));
  return {n, flushMs: +(t1 - t0).toFixed(1)};
};
w.ready = true;
EOF
